files.src/BoxEdges.st:
(*
 * Box Edges - one pulse when a box arrives and one when it leaves.
 *
 * R_TRIG gives TRUE for one scan on the change of its input from FALSE to TRUE, and F_TRIG on the change from TRUE to FALSE.
 *)

PROGRAM BoxEdges

VAR_INPUT
    BoxSensor AT %I0.0 : BOOL;
END_VAR

VAR
    ArrivedTrig : R_TRIG;
    LeftTrig : F_TRIG;
END_VAR

VAR_OUTPUT
    BoxArrived AT %Q0.0 : BOOL;
    BoxLeft AT %Q0.1 : BOOL;
END_VAR

ArrivedTrig(CLK := BoxSensor);
LeftTrig(CLK := BoxSensor);
BoxArrived := ArrivedTrig.Q;
BoxLeft := LeftTrig.Q;

END_PROGRAM

